const int MAXN = 1000;
const int MAXM = 100100;
const int INF = (1<<29);

int edges[2*MAXM], flowValues[2*MAXM], capacity[2*MAXM], nextEdge[2*MAXM];
int head[MAXN], current[MAXN], level[MAXN], queueArr[MAXN];
int totalEdges, totalNodes, sourceNode, sinkNode, frontIdx, rearIdx;

void setupFlow(int nodes, int sNode, int tNode) {
    totalNodes = nodes; sourceNode = sNode; sinkNode = tNode; totalEdges=2;
    for (int i=0; i<=totalNodes; i++) head[i]=0;
}
void addEdge(int u, int v, int capVal) {
    edges[totalEdges]=v; flowValues[totalEdges]=0; capacity[totalEdges]=capVal; nextEdge[totalEdges]=head[u]; head[u]=totalEdges++;
    edges[totalEdges]=u; flowValues[totalEdges]=0; capacity[totalEdges]=0; nextEdge[totalEdges]=head[v]; head[v]=totalEdges++;
}
bool buildLevelGraph() {
    for (int i=0; i<=totalNodes; i++) level[i]=0;
    frontIdx=rearIdx=0;
    queueArr[frontIdx++]=sourceNode;
    level[sourceNode]=1;
    while (rearIdx<frontIdx && !level[sinkNode]) {
        int u=queueArr[rearIdx++];
        for (int e=head[u]; e; e=nextEdge[e]) {
            int v=edges[e];
            if (!level[v] && flowValues[e]<capacity[e]) {
                level[v]=level[u]+1;
                queueArr[frontIdx++]=v;
            }
        }
    }
    return level[sinkNode]!=0;
}
int sendFlow(int u, int flowAmt) {
    if (u==sinkNode) return flowAmt;
    for (int &e=current[u], f=0; e; e= current[u]=nextEdge[e]) {
        int v=edges[e];
        if (level[u]<level[v] && flowValues[e]<capacity[e] && (f=sendFlow(v, min(flowAmt, capacity[e]-flowValues[e])))) {
            flowValues[e]+=f;
            flowValues[e^1]-=f;
            return f;
        }
    }
    return 0;
}
int computeMaxFlow() {
    int totalFlow=0, f;
    while (buildLevelGraph()) {
        for (int i=0; i<=totalNodes; i++) current[i]=head[i];
        while ((f=sendFlow(sourceNode, INF))) totalFlow+=f;
    }
    return totalFlow;
}

int R;
string gridA[MAXR], gridB[MAXR];

int dirI[] = {0,1,0,-1};
int dirJ[] = {1,0,-1,0};

bool canProceed(int i, int j) {
