import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static final int MAXR = 11;
    static final int MAXN = 1000;
    static final int MAXM = 100100;
    static final int INF = 1 << 29;

    static int[] edges = new int[2 * MAXM];
    static int[] flowValues = new int[2 * MAXM];
    static int[] capacity = new int[2 * MAXM];
    static int[] nextEdge = new int[2 * MAXM];
    static int[] head = new int[MAXN + 1];
    static int[] current = new int[MAXN + 1];
    static int[] level = new int[MAXN + 1];
    static int[] queueArr = new int[MAXN + 1];

    static int totalEdges, totalNodes, sourceNode, sinkNode;
    static int frontIdx, rearIdx;

    static String[] gridA = new String[MAXR];
    static String[] gridB = new String[MAXR];

    static int[] dirI = {0, 1, 0, -1};
    static int[] dirJ = {1, 0, -1, 0};

    static int[][][] timeMatrix = new int[2][MAXR][MAXR];
    static int[][][] nodeIDMap = new int[2][MAXR][MAXR];

    static int R, T, zi, zj;

    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x; this.y = y;
        }
    }

    static void setupFlow(int nodes, int sNode, int tNode) {
        totalNodes = nodes;
        sourceNode = sNode;
        sinkNode = tNode;
        totalEdges = 2;
        Arrays.fill(head, 0, totalNodes + 1, 0);
    }

    static void addEdge(int u, int v, int capVal) {
        edges[totalEdges] = v;
        flowValues[totalEdges] = 0;
        capacity[totalEdges] = capVal;
        nextEdge[totalEdges] = head[u];
        head[u] = totalEdges++;
        edges[totalEdges] = u;
        flowValues[totalEdges] = 0;
        capacity[totalEdges] = 0;
        nextEdge[totalEdges] = head[v];
        head[v] = totalEdges++;
    }

    static boolean buildLevelGraph() {
        Arrays.fill(level, 0, totalNodes + 1, 0);
        frontIdx = rearIdx = 0;
        queueArr[frontIdx++] = sourceNode;
        level[sourceNode] = 1;
        while (rearIdx < frontIdx && level[sinkNode] == 0) {
            int u = queueArr[rearIdx++];
            for (int e = head[u]; e != 0; e = nextEdge[e]) {
                int v = edges[e];
                if (level[v] == 0 && flowValues[e] < capacity[e]) {
                    level[v] = level[u] + 1;
                    queueArr[frontIdx++] = v;
                }
            }
        }
        return level[sinkNode] != 0;
    }

    static int sendFlow(int u, int flowAmt) {
        if (u == sinkNode) return flowAmt;
        for (int e = current[u]; e != 0; e = current[u] = nextEdge[e]) {
            int v = edges[e];
            if (level[u] < level[v] && flowValues[e] < capacity[e]) {
                int f = sendFlow(v, Math.min(flowAmt, capacity[e] - flowValues[e]));
                if (f > 0) {
                    flowValues[e] += f;
                    flowValues[e ^ 1] -= f;
                    return f;
                }
            }
        }
        return 0;
    }

    static int computeMaxFlow() {
        int totalFlow = 0, f;
        while (buildLevelGraph()) {
            for (int i = 0; i <= totalNodes; i++) {
                current[i] = head[i];
            }
            while ((f = sendFlow(sourceNode, INF)) > 0) {
                totalFlow += f;
            }
        }
        return totalFlow;
    }

    static boolean canProceed(int i, int j) {
        return (i >= 0 && j >= 0 && i < R && j < R && gridA[i].charAt(j) != 'Y' && gridA[i].charAt(j) != 'Z');
    }

    static void runBFS(int i, int j, int c) {
        for (int k = 0; k < R; k++) {
            for (int l = 0; l < R; l++) {
                timeMatrix[c][k][l] = 0;
            }
        }
        timeMatrix[c][i][j] = 1;
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(i, j));
        while (!q.isEmpty()) {
            Point p = q.poll();
            int x = p.x, y = p.y;
            if (c == 1 && (timeMatrix[0][x][y] != 0 && timeMatrix[0][x][y] <= timeMatrix[1][x][y])) continue;
            for (int k = 0; k < 4; k++) {
                int ni = x + dirI[k], nj = y + dirJ[k];
                if (canProceed(ni, nj) && timeMatrix[c][ni][nj] == 0) {
                    timeMatrix[c][ni][nj] = timeMatrix[c][x][y] + 1;
                    q.offer(new Point(ni, nj));
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        zi = 0;
        zj = 0;
        int totalNodes = 0;
        int start = 0;
        int end = 0;

        for (int i = 0; i < R; i++) {
            gridA[i] = br.readLine();
        }
        for (int i = 0; i < R; i++) {
            gridB[i] = br.readLine();
        }

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (gridA[i].charAt(j) == 'Z') {
                    zi = i;
                    zj = j;
                } else if (gridA[i].charAt(j) != 'Y') {
                    totalNodes++;
                    nodeIDMap[0][i][j] = totalNodes;
                }
            }
        }

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (gridB[i].charAt(j) != 'Y' && gridB[i].charAt(j) != 'Z') {
                    totalNodes++;
                    nodeIDMap[1][i][j] = totalNodes;
                }
            }
        }

        totalNodes++;
        start = 0;
        end = totalNodes;
        setupFlow(totalNodes, start, end);

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (gridA[i].charAt(j) != 'Z' && gridA[i].charAt(j) != 'Y') {
                    addEdge(start, nodeIDMap[0][i][j], gridA[i].charAt(j) - '0');
                    addEdge(nodeIDMap[1][i][j], end, gridB[i].charAt(j) - '0');
                }
            }
        }

        runBFS(zi, zj, 0);

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (gridA[i].charAt(j) > '0' && gridA[i].charAt(j) <= '9') {
                    runBFS(i, j, 1);
                    for (int ii = 0; ii < R; ii++) {
                        for (int jj = 0; jj < R; jj++) {
                            if (gridB[ii].charAt(jj) > '0' && gridB[ii].charAt(jj) <= '9') {
                                if (timeMatrix[1][ii][jj] != 0 && (timeMatrix[0][ii][jj] == 0 || timeMatrix[0][ii][jj] >= timeMatrix[1][ii][jj]) && timeMatrix[1][ii][jj] - 1 <= T) {
                                    addEdge(nodeIDMap[0][i][j], nodeIDMap[1][ii][jj], INF);
                                }
                            }
                        }
                    }
                }
            }
        }

        System.out.println(computeMaxFlow());
    }
}
